import json
import re
from docx import Document

def fill_template(template_path, data_path, output_path):
    # Load data
    with open(data_path) as f:
        data = json.load(f)

    # Load template
    doc = Document(template_path)

    relocation_enabled = data.get('RELOCATION_PACKAGE') == 'Yes'

    # Track if we are inside a relocation block to handle multi-paragraph removal
    in_relocation_block = False

    def replace_in_para(para):
        nonlocal in_relocation_block
        text = para.text

        # Check for start of conditional block
        if '{{IF_RELOCATION}}' in text:
            in_relocation_block = True
            text = text.replace('{{IF_RELOCATION}}', '')

        # If we are in the block and relocation is NOT enabled, clear the content
        if in_relocation_block and not relocation_enabled:
            # We still need to check if the end marker is in this same paragraph
            if '{{END_IF_RELOCATION}}' in text:
                # If both are in the same paragraph, we remove everything between them
                # But for simplicity, we'll just handle the end marker below
                pass
            else:
                text = ''

        # Check for end of conditional block
        if '{{END_IF_RELOCATION}}' in text:
            # If we were removing, we might have some text after the end marker
            # but usually these markers are on their own lines or at ends
            in_relocation_block = False
            text = text.replace('{{END_IF_RELOCATION}}', '')

        # Replace standard placeholders
        pattern = r'\{\{([A-Z_]+)\}\}'
        matches = re.findall(pattern, text)
        for key in matches:
            placeholder = '{{' + key + '}}'
            if key in data:
                text = text.replace(placeholder, str(data[key]))

        if text != para.text:
            if para.runs:
                # Preserve formatting of the first run
                para.runs[0].text = text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                para.text = text

    def process_paragraphs(paragraphs):
        for para in paragraphs:
            replace_in_para(para)

    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                process_paragraphs(cell.paragraphs)
                for nested in cell.tables:
                    process_table(nested)

    # Main document
    process_paragraphs(doc.paragraphs)

    # Tables
    for table in doc.tables:
        process_table(table)

    # Headers/Footers
    for section in doc.sections:
        process_paragraphs(section.header.paragraphs)
        process_paragraphs(section.footer.paragraphs)

    doc.save(output_path)

if __name__ == '__main__':
    fill_template('offer_letter_template.docx', 'employee_data.json', 'offer_letter_filled.docx')

